toolCalls:
Bash: T=tmp/claude-501 && {
printf '%s\n' '# Ops notebook' 'Notes from the on-call week.' '## Rotate the keys' '- Generate the new key pair' '- Upload the public key' '- Retire the old key' \
  '## Fix the reaper' '- The reaper skips jobs that finish during a restart' '- Reproduce it with a restart in the middle of a sweep' '- Patch the cursor so it resumes from the last job' '- Add a test for the restart case' \
  '## Sweep the logs' '- Find the logs older than a week' '- Compress them into the archive' '- Delete the originals'
for d in $(seq 1 24); do printf '## Day %d\n' "$d"; for k in $(seq 1 7); do printf -- '- Check item %d of day %d\n' "$k" "$d"; done; done
} > $T/reaper.md && wc -lc $T/reaper.md && LC_ALL=C grep -c '[^ -~]' $T/reaper.md; jq --rawfile t $T/reaper.md '.files["reaper.md"] = $t' $T/check.template.json > work/check.json && bin/palantir-accept lint work/check.json rule.md

Bash: T=tmp/claude-501 && {
printf '%s\n' '# Ops notebook' 'Notes from the on-call week.' '## Rotate the keys' '- Generate the new key pair' '- Upload the public key' '- Retire the old key' \
  '## Fix the reaper' '- The reaper skips jobs that finish during a restart' '- Reproduce it with a restart in the middle of a sweep' '- Patch the cursor so it resumes from the last job' '- Add a test for the restart case' \
  '## Sweep the logs' '- Find the logs older than a week' '- Compress them into the archive' '- Delete the originals'
d=1; while [ $d -le 24 ]; do printf '## Day %d\n' "$d"; k=1; while [ $k -le 7 ]; do printf -- '- Check item %d of day %d\n' "$k" "$d"; k=$((k+1)); done; d=$((d+1)); done
} > $T/reaper.md && wc -lc $T/reaper.md && LC_ALL=C grep -c '[^ -~]' $T/reaper.md; sed -n '1,20p;$p' $T/reaper.md; jq --rawfile t $T/reaper.md '.files["reaper.md"] = $t' $T/check.template.json > work/check.json && jq -r '.files["reaper.md"] | length' work/check.json && bin/palantir-accept lint work/check.json rule.md

Bash: cp work/check.json tmp/check.before.json &&
jq --rawfile menu tmp/expr/menu.jq --rawfile adj tmp/expr/adjacent.jq --rawfile gaps tmp/expr/gaps.jq --rawfile still tmp/expr/still.jq '
  def t: sub("\n$"; "");
  .steps[1].do[4].drive[1].jq = ($menu | t)
  | .steps[2].expect[0] = {that: ($adj | t), why: "right after the fold and again a second later, the next visible line is drawn directly under the heading, within a pixel"}
  | .steps[2].expect[1] = {that: ($gaps | t), why: "right after the fold and again a second later, no blank space is left between the heading and the next visible line"}
  | .steps[3].expect[1] = {that: ($still | t), why: "folding did not move the heading on screen: in every state read from before the fold to now, its point on the screen is exactly where it was"}
' tmp/check.before.json > work/check.json && bin/palantir-accept lint work/check.json rule.md; echo "exit $?"; diff <(jq . tmp/check.before.json) <(jq . work/check.json)

